create table purchase_order (id bigint generated by default as identity primary key, version bigint not null, owner varchar(255) not null, product varchar(255) not null, quantity integer not null, total_cents bigint not null, status varchar(255) not null, created_at timestamp with time zone not null, payment_id varchar(255), checkout_id varchar(255), refund_id varchar(255), checkout_url varchar(2048));
create table account (email varchar(255) primary key, password varchar(255) not null, verified boolean not null);
create table auth_token (hash varchar(64) primary key, email varchar(255) not null, kind varchar(32) not null, family varchar(255) not null, expires_at timestamp with time zone not null, consumed boolean not null);
create table payment_event (id varchar(255) primary key);
create table attachment (id varchar(255) primary key, owner varchar(255) not null, filename varchar(255) not null);
